帮我看一下这段代码，提交上去 WA 了。题目是：给一个数组 a[1..n]，每次操作可以选相邻两个数，把较小的删掉。问最后剩下的数最大可能是多少。n ≤ 2×10^5, a[i] ≤ 10^9。

```cpp
#include <bits/stdc++.h>
using namespace std;

void solve() {
    int n; cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    int ans = 1;
    for (int i = 0; i < n; i++) {
        ans = ans * a[i] % 1000000007;
    }
    cout << ans << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t; cin >> t; while (t--) solve();
}
```

